class PieChartWidget(QWidget):
    def __init__(self, values=None, parent=None, title=""):
        super().__init__(parent)
        self.values = values or {}
        self.title = title or ""
        self.setMinimumHeight(220)
        self.setMinimumWidth(240)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.setStyleSheet("background:#FFFFFF;border:1px solid #D6E2EE;border-radius:8px;")

    def set_values(self, values):
        self.values = values or {}
        self.update()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.fillRect(self.rect(), QColor("#FFFFFF"))
        title_h = 22 if self.title else 0
        if self.title:
            painter.setPen(QPen(QColor("#17365D")))
            painter.setFont(QFont("Segoe UI", 10, QFont.Weight.Bold))
            painter.drawText(12, 16, self.title)
        body = self.rect().adjusted(10, 8 + title_h, -10, -8)
        total = sum(max(0, int(v)) for v in self.values.values())
        if total <= 0:
            painter.setPen(QPen(QColor("#888888")))
            painter.drawText(body, Qt.AlignmentFlag.AlignCenter, "No data in selected filters")
            painter.end()
            return
        items = list(self.values.items())[:12]
        # Prefer side legend when wide enough; otherwise stack legend under the pie to avoid overlap.
        side_legend = body.width() >= 320 and body.height() >= 160
        if side_legend:
            pie_area = QRectF(body.left(), body.top(), body.width() * 0.55, body.height())
            legend_area = QRectF(pie_area.right() + 8, body.top(), body.width() - pie_area.width() - 8, body.height())
        else:
            pie_h = max(80, int(body.height() * 0.62))
            pie_area = QRectF(body.left(), body.top(), body.width(), pie_h)
            legend_area = QRectF(body.left(), pie_area.bottom() + 4, body.width(), body.height() - pie_h - 4)
        radius = max(28, min(int(pie_area.width()), int(pie_area.height())) // 2 - 6)
        center = pie_area.center()
        start = 0
        palette = [
            QColor("#1F4E79"), QColor("#2E86AB"), QColor("#28A745"), QColor("#F39C12"),
            QColor("#E74C3C"), QColor("#8E44AD"), QColor("#16A085"), QColor("#7F8C8D"),
            QColor("#C0392B"), QColor("#2980B9"), QColor("#27AE60"), QColor("#D35400"),
        ]
        for i, (label, value) in enumerate(items):
            value = max(0, int(value))
            span = int(round(360 * 16 * value / total))
            painter.setBrush(QBrush(palette[i % len(palette)]))
            painter.setPen(QPen(QColor("#FFFFFF"), 2))
            painter.drawPie(
                QRectF(center.x() - radius, center.y() - radius, 2 * radius, 2 * radius),
                start, span
            )
            start += span
        painter.setFont(QFont("Segoe UI", 8 if not side_legend else 9))
        if side_legend:
            legend_x = int(legend_area.left())
            legend_y = int(legend_area.top()) + 4
            for i, (label, value) in enumerate(items):
                painter.setBrush(QBrush(palette[i % len(palette)]))
                painter.setPen(QPen(QColor("#FFFFFF")))
                painter.drawRoundedRect(legend_x, legend_y, 11, 11, 2, 2)
                painter.setPen(QPen(QColor("#333333")))
                pct = int(round(100 * int(value) / total)) if total else 0
                painter.drawText(legend_x + 16, legend_y + 10, f"{str(label)[:16]}  {value} ({pct}%)")
                legend_y += 16
                if legend_y > legend_area.bottom() - 12:
                    break
        else:
            # Compact multi-column legend under the pie
            cols = 2 if body.width() > 220 else 1
            col_w = int(legend_area.width() / cols)
            for i, (label, value) in enumerate(items):
                col = i % cols
                row = i // cols
                lx = int(legend_area.left()) + col * col_w
                ly = int(legend_area.top()) + row * 15
                if ly > legend_area.bottom() - 10:
                    break
                painter.setBrush(QBrush(palette[i % len(palette)]))
                painter.setPen(QPen(QColor("#FFFFFF")))
                painter.drawRoundedRect(lx, ly, 10, 10, 2, 2)
                painter.setPen(QPen(QColor("#333333")))
                pct = int(round(100 * int(value) / total)) if total else 0
                painter.drawText(lx + 14, ly + 9, f"{str(label)[:12]} {pct}%")
        painter.end()


class BarChartWidget(QWidget):
    def __init__(self, values=None, parent=None, title=""):
        super().__init__(parent)
        self.values = values or {}
        self.title = title or ""
        self.setMinimumHeight(220)
        self.setMinimumWidth(260)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.setStyleSheet("background:#FFFFFF;border:1px solid #D6E2EE;border-radius:8px;")

    def set_values(self, values):
        self.values = values or {}
        self.update()

    def paintEvent(self, event):
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)
        painter.fillRect(self.rect(), QColor("#FFFFFF"))
        title_h = 22 if self.title else 0
        if self.title:
            painter.setPen(QPen(QColor("#17365D")))
            painter.setFont(QFont("Segoe UI", 10, QFont.Weight.Bold))
            painter.drawText(12, 16, self.title)
        # Leave room at bottom for rotated labels; scale with widget height to reduce overlap.
        bottom_pad = max(36, min(64, self.height() // 6))
        left_pad = 40
        rect = self.rect().adjusted(left_pad, 8 + title_h, -12, -bottom_pad)
        if not self.values:
            painter.setPen(QPen(QColor("#888888")))
            painter.drawText(rect, Qt.AlignmentFlag.AlignCenter, "No data in selected filters")
            painter.end()
            return
        maxv = max([int(v) for v in self.values.values()] or [1]) or 1
        count = max(len(self.values), 1)
        usable = max(1, rect.width())
        barw = max(12, min(48, int(usable / count * 0.55)))
        gap = max(4, int((usable - barw * count) / max(count, 1)))
        x = rect.left()
        colors = [
            QColor("#1F4E79"), QColor("#2E86AB"), QColor("#28A745"), QColor("#F39C12"),
            QColor("#E74C3C"), QColor("#8E44AD"), QColor("#16A085"), QColor("#7F8C8D"),
        ]
        painter.setPen(QPen(QColor("#E8EEF4"), 1))
        for g in range(5):
            gy = rect.bottom() - int(rect.height() * g / 4)
            painter.drawLine(rect.left(), gy, rect.right(), gy)
        painter.setFont(QFont("Segoe UI", 8))
        for i, (label, value) in enumerate(self.values.items()):
            value = int(value)
            h = int(rect.height() * value / maxv) if maxv else 0
            y = rect.bottom() - h
            color = colors[i % len(colors)]
            painter.setBrush(QBrush(color))
            painter.setPen(QPen(color.darker(110), 1))
            painter.drawRoundedRect(int(x), y, barw, max(h, 1), 3, 3)
            painter.setPen(QPen(QColor("#17365D")))
            val_txt = str(value)
            tw = painter.fontMetrics().horizontalAdvance(val_txt)
            painter.drawText(int(x + (barw - tw) / 2), y - 3, val_txt)
            painter.save()
            painter.translate(x + barw / 2, rect.bottom() + 8)
            painter.rotate(-35)
            painter.setPen(QPen(QColor("#444444")))
            max_chars = max(6, min(18, int(90 / max(barw, 12))))
            painter.drawText(0, 0, str(label)[:max_chars])
            painter.restore()
            x += barw + gap
        painter.setPen(QPen(QColor("#17365D"), 1.5))
        painter.drawLine(rect.left(), rect.bottom(), rect.right(), rect.bottom())
        painter.end()



class BodyAnatomyWidget(QWidget):
    """Human body map showing injured body-part percentages (not a bar chart)."""

    # Relative regions within body drawing coordinates (0-100 x, 0-200 y)
    REGIONS = {
        "Head": (42, 4, 16, 16),
        "Face": (44, 12, 12, 10),
        "Eye(s)": (45, 12, 10, 5),
        "Ear(s)": (38, 14, 6, 8),
        "Neck": (46, 20, 8, 8),
        "Shoulder": (28, 28, 44, 10),
        "Chest": (38, 36, 24, 22),
        "Back": (40, 38, 20, 24),
        "Abdomen": (40, 56, 20, 16),
        "Arm": (18, 32, 12, 40),
        "Elbow": (18, 50, 12, 10),
        "Wrist": (18, 68, 12, 8),
        "Hand": (16, 74, 14, 12),
        "Finger(s)": (16, 82, 14, 10),
        "Hip": (38, 70, 24, 12),
        "Leg": (38, 80, 10, 40),
        "Knee": (38, 108, 10, 10),
        "Ankle": (38, 140, 10, 8),
        "Foot": (34, 148, 16, 10),
        "Toe(s)": (34, 154, 16, 6),
        "Multiple Parts": (70, 180, 26, 10),
        "Other / Not Specified": (2, 180, 30, 10),
    }

    def __init__(self, values=None, parent=None, title="Body Parts Injured"):
        super().__init__(parent)
        self.values = values or {}
        self.title = title
        self.setMinimumHeight(320)
        self.setMinimumWidth(280)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        self.setStyleSheet("background:#FFFFFF;border:1px solid #D6E2EE;border-radius:8px;")

    def set_values(self, values):
        self.values = values or {}
        self.update()

    def _heat(self, pct):
        """Map 0-100% to cool→hot colour."""
        pct = max(0.0, min(100.0, float(pct)))
        if pct <= 0:
            return QColor("#E8EEF4")
        if pct < 15:
            return QColor("#FDE68A")
        if pct < 30:
            return QColor("#FBBF24")
        if pct < 50:
            return QColor("#F97316")
        if pct < 70:
            return QColor("#EF4444")
        return QColor("#B91C1C")

    def paintEvent(self, event):
        from PySide6.QtGui import QPainter, QPen, QBrush, QFont, QPainterPath
        from PySide6.QtCore import QRectF, QPointF
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.fillRect(self.rect(), QColor("#FFFFFF"))
        p.setPen(QPen(QColor("#17365D")))
        p.setFont(QFont("Segoe UI", 10, QFont.Weight.Bold))
        p.drawText(12, 18, self.title or "Body Parts Injured")

        total = sum(max(0, int(v)) for v in self.values.values()) or 0
        # Layout: body on left, legend on right
        area = self.rect().adjusted(10, 28, -10, -10)
        body_w = int(area.width() * 0.48)
        body_h = area.height()
        # Body coordinate system 0-100 x, 0-170 y mapped into body rect
        ox, oy = area.left() + 8, area.top() + 4
        scale_x = (body_w - 16) / 100.0
        scale_y = (body_h - 8) / 170.0

        def R(x, y, w, h):
            return QRectF(ox + x * scale_x, oy + y * scale_y, w * scale_x, h * scale_y)

        # Silhouette base (light)
        p.setPen(QPen(QColor("#94A3B8"), 1.5))
        p.setBrush(QBrush(QColor("#F1F5F9")))
        # Head
        p.drawEllipse(R(40, 2, 20, 22))
        # Neck
        p.drawRoundedRect(R(46, 22, 8, 8), 2, 2)
        # Torso
        p.drawRoundedRect(R(34, 28, 32, 48), 8, 8)
        # Arms
        p.drawRoundedRect(R(14, 30, 18, 50), 6, 6)
        p.drawRoundedRect(R(68, 30, 18, 50), 6, 6)
        # Legs
        p.drawRoundedRect(R(36, 74, 12, 70), 5, 5)
        p.drawRoundedRect(R(52, 74, 12, 70), 5, 5)
        # Feet
        p.drawRoundedRect(R(32, 142, 16, 10), 3, 3)
        p.drawRoundedRect(R(52, 142, 16, 10), 3, 3)

        # Heat overlay for parts that have counts
        pct_map = {}
        for part, count in self.values.items():
            pct_map[part] = (100.0 * int(count) / total) if total else 0.0

        # Map aliases
        alias = {
            "Eye": "Eye(s)", "Eyes": "Eye(s)", "Ear": "Ear(s)", "Ears": "Ear(s)",
            "Fingers": "Finger(s)", "Finger": "Finger(s)", "Toes": "Toe(s)", "Toe": "Toe(s)",
        }

        # Paint heat regions
        for name, (x, y, w, h) in self.REGIONS.items():
            key = name
            count = 0
            if name in self.values:
                count = int(self.values[name])
            else:
                for k, v in self.values.items():
                    if k.lower() == name.lower() or alias.get(k) == name:
                        count = int(v); break
            if count <= 0 and name not in ("Multiple Parts", "Other / Not Specified"):
                continue
            pct = pct_map.get(name, 0)
            if count > 0:
                col = self._heat(pct)
                col.setAlpha(200)
                p.setBrush(QBrush(col))
                p.setPen(QPen(col.darker(120), 1))
                p.drawRoundedRect(R(x, y, w, h), 3, 3)
                # percentage label on region if large enough
                if w * scale_x > 18 and h * scale_y > 12:
                    p.setPen(QColor("#FFFFFF") if pct >= 30 else QColor("#1E293B"))
                    p.setFont(QFont("Segoe UI", 7, QFont.Weight.Bold))
                    p.drawText(R(x, y, w, h), Qt.AlignmentFlag.AlignCenter, f"{pct:.0f}%")

        # Outline silhouette again for clarity
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.setPen(QPen(QColor("#334155"), 1.8))
        p.drawEllipse(R(40, 2, 20, 22))
        p.drawRoundedRect(R(34, 28, 32, 48), 8, 8)
        p.drawRoundedRect(R(14, 30, 18, 50), 6, 6)
        p.drawRoundedRect(R(68, 30, 18, 50), 6, 6)
        p.drawRoundedRect(R(36, 74, 12, 70), 5, 5)
        p.drawRoundedRect(R(52, 74, 12, 70), 5, 5)

        # Legend on the right
        lx = area.left() + body_w + 12
        ly = area.top() + 4
        p.setFont(QFont("Segoe UI", 8, QFont.Weight.Bold))
        p.setPen(QColor("#17365D"))
        p.drawText(lx, ly + 10, f"Total injuries tagged: {total}")
        ly += 22
        p.setFont(QFont("Segoe UI", 8))
        items = sorted(self.values.items(), key=lambda kv: -int(kv[1]))[:14]
        if not items:
            p.setPen(QColor("#888888"))
            p.drawText(lx, ly + 12, "No body-part data yet")
        for name, count in items:
            pct = (100.0 * int(count) / total) if total else 0
            col = self._heat(pct)
            p.setBrush(QBrush(col))
            p.setPen(QPen(QColor("#FFFFFF")))
            p.drawRoundedRect(lx, ly, 12, 12, 2, 2)
            p.setPen(QColor("#334155"))
            p.drawText(lx + 16, ly + 11, f"{str(name)[:18]}  {count} ({pct:.0f}%)")
            ly += 16
            if ly > area.bottom() - 20:
                break
        # Heat scale
        ly = max(ly + 8, area.bottom() - 28)
        p.setFont(QFont("Segoe UI", 7))
        p.setPen(QColor("#64748B"))
        p.drawText(lx, ly, "Low → High injury share")
        for i, pct in enumerate((5, 20, 40, 60, 85)):
            p.setBrush(QBrush(self._heat(pct)))
            p.setPen(QPen(QColor("#FFFFFF")))
            p.drawRect(lx + i * 18, ly + 6, 16, 10)
        p.end()


