        def add_tile(grid, row, col, label_text, widget, key=None):
            tile = QWidget()
            tile_layout = QVBoxLayout(tile)
            tile_layout.setContentsMargins(0, 0, 0, 0)
            tile_layout.setSpacing(4)
            label = QLabel(label_text)
