# RISK ASSESSMENT MODULE  (additive – does not alter other modules)
# Types: Risk Assessment | JSA | JHA | Dynamic Risk Assessment
# Library: Construction + Oil & Gas – multi-row tasks, extended JSA/JHA steps
# ============================================================

RA_TYPES = [
    "Risk Assessment",
    "Job Safety Analysis (JSA)",
    "Job Hazard Analysis (JHA)",
    "Dynamic Risk Assessment",
]

RA_SECTORS = [
    "Construction",
    "Oil & Gas",
    "Construction – Oil & Gas Interface",
]

RA_LIKELIHOOD = [
    (1, "Rare"),
    (2, "Unlikely"),
    (3, "Possible"),
    (4, "Likely"),
    (5, "Almost Certain"),
]
RA_SEVERITY = [
    (1, "Insignificant"),
    (2, "Minor"),
    (3, "Moderate"),
    (4, "Major"),
    (5, "Catastrophic"),
]

def ra_band(score):
    try:
        s = int(score)
    except Exception:
        s = 0
    if s <= 4:
        return "Low"
    if s <= 9:
        return "Medium"
    if s <= 15:
        return "High"
    return "Extreme"


def ra_band_color(band):
    return {
        "Low": "#C6E0B4",
        "Medium": "#FFE699",
        "High": "#F8CBAD",
        "Extreme": "#FF6B6B",
    }.get(band, "#FFFFFF")


def ra_score_color(score):
    return ra_band_color(ra_band(score))


