class RiskAssessmentModule(QWidget):
    """Risk Assessment / JSA / JHA / Dynamic RA – additive only."""

    def __init__(self, parent_window, db):
        super().__init__(parent_window)
        self.host = parent_window
        self.db = db
        self.current_rows = []
        self.current_meta = {}
        self._editing_id = None
        self._risk_update_blocked = False
        self._ensure_schema()
        self._build_ui()
        self.refresh_register()

    def _ensure_schema(self):
        self.db.conn.executescript("""
        CREATE TABLE IF NOT EXISTS risk_assessments (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            number TEXT UNIQUE,
            ra_type TEXT NOT NULL,
            sector TEXT DEFAULT '',
            activity TEXT DEFAULT '',
            title TEXT DEFAULT '',
            project TEXT DEFAULT '',
            location TEXT DEFAULT '',
            department TEXT DEFAULT '',
            assessor TEXT DEFAULT '',
            assessment_date TEXT DEFAULT '',
            review_date TEXT DEFAULT '',
            status TEXT DEFAULT 'Draft',
            ppe TEXT DEFAULT '',
            remarks TEXT DEFAULT '',
            rows_json TEXT DEFAULT '[]',
            created_at TEXT DEFAULT '',
            updated_at TEXT DEFAULT ''
        );
        CREATE INDEX IF NOT EXISTS idx_ra_number ON risk_assessments(number);
        CREATE INDEX IF NOT EXISTS idx_ra_type ON risk_assessments(ra_type);
        """)
        # Additive migration: existing assessment records and columns are preserved.
        existing = {r[1] for r in self.db.conn.execute("PRAGMA table_info(risk_assessments)").fetchall()}
        additions = {
            "hse_reviewer": "TEXT DEFAULT ''",
            "hse_reviewed_at": "TEXT DEFAULT ''",
            "management_approver": "TEXT DEFAULT ''",
            "management_approved_at": "TEXT DEFAULT ''",
            "workflow_note": "TEXT DEFAULT ''",
            "parent_id": "INTEGER",
            "revision": "INTEGER DEFAULT 0",
            "submitted_at": "TEXT DEFAULT ''",
        }
        for col, definition in additions.items():
            if col not in existing:
                self.db.conn.execute(f"ALTER TABLE risk_assessments ADD COLUMN {col} {definition}")
        self.db.conn.commit()

    def _actor(self):
        return os.environ.get("USERNAME") or os.environ.get("USER") or "User"

    def _next_number(self):
        year = datetime.now().year
        rows = self.db.fetchall(
            "SELECT number FROM risk_assessments WHERE number LIKE ?",
            (f"HSE-RA-{year}-%",)
        )
        highest = 0
        for row in rows:
            match = re.search(r"-(\d{5})(?:-R\d+)?$", str(row["number"] or ""))
            if match:
                highest = max(highest, int(match.group(1)))
        return f"HSE-RA-{year}-{highest + 1:05d}"

    def _build_ui(self):
        root = QVBoxLayout(self)
        root.setContentsMargins(8, 8, 8, 8)
        head = QLabel("RISK ASSESSMENT  |  JSA  |  JHA  |  DYNAMIC RA")
        head.setStyleSheet("font-size:22px;font-weight:bold;color:#17365D;padding:6px;")
        root.addWidget(head)
        note = QLabel(
            "Tab 1: choose type, sector and activity, then Load Library. "
            "Tab 2 shows a full multi-row assessment (5+ tasks for Risk Assessment; extended steps for JSA/JHA) "
            "with automatic risk score updates when you change Likelihood or Severity. "
            "Tab 3 is the 5×5 matrix. Tab 4 is the register."
        )
        note.setWordWrap(True)
        note.setStyleSheet("padding:8px;background:#E8F1FB;border:1px solid #B7C9D6;border-radius:4px;color:#17365D;")
        root.addWidget(note)

